import { BLOCK_MATERIALS, type MaterialKey, type Vec3 } from '../blockout/types'
import { CONTAINER_LABELS, SITE_LABELS, USE_LABELS, type BlockoutShape, type Container, type PropFamily, type Rarity, type Resource, type ResourceCategory, type SiteTag, type Use } from './types'

const RARITY: Record<'c' | 'i' | 'r' | 'm', Rarity> = { c: 'comum', i: 'incomum', r: 'raro', m: 'muito-raro' }
const SHAPES = new Set<BlockoutShape>(['box', 'pack', 'can', 'bottle', 'jar', 'jug', 'sack', 'bundle', 'stack', 'coil', 'roll', 'tube', 'tank', 'device', 'tool', 'bar', 'blade', 'longgun', 'pistol', 'mag', 'pouch', 'pile', 'sheet', 'spool', 'bag'])
const PROPS = new Set<PropFamily>(['medicine', 'bandages', 'cans', 'food-box', 'bottles', 'ammo', 'handgun', 'toolbox', 'cloth', 'battery', 'seeds', 'papers', 'plastic'])

const DISPLAY: Record<ResourceCategory, PropFamily> = {
  metal: 'toolbox', construcao: 'toolbox', plastico: 'plastic', quimico: 'bottles', combustivel: 'bottles', eletrico: 'battery', medico: 'medicine', higiene: 'plastic', alimento: 'food-box',
  bebida: 'bottles', arma: 'handgun', 'peca-arma': 'handgun', municao: 'ammo', ferramenta: 'toolbox', tecido: 'cloth', agricola: 'seeds', utilidade: 'plastic', documento: 'papers', sucata: 'plastic',
}

const words = <T extends string>(text: string, valid: Record<T, unknown>, id: string, field: string) => text.split(/\s+/).filter(Boolean).map((token) => {
  if (!(token in valid)) throw new Error(`Recurso ${id}: ${field} desconhecido "${token}"`)
  return token as T
})

function R(id: string, label: string, category: ResourceCategory, rarity: keyof typeof RARITY, weight: number, quantity: string, uses: string, containers: string, sites: string, model: string, display?: PropFamily): Resource {
  const [min, max] = quantity.split('-').map(Number)
  const affinity: Resource['sites'] = {}
  for (const token of sites.split(/\s+/).filter(Boolean)) {
    const [tag, value] = token.split(':')
    if (tag !== '*' && !(tag in SITE_LABELS)) throw new Error(`Recurso ${id}: estrutura desconhecida "${tag}"`)
    affinity[tag as SiteTag | '*'] = Number(value)
  }
  let parsed: Resource['model']
  if (model.startsWith('@')) {
    const family = model.slice(1) as PropFamily
    if (!PROPS.has(family)) throw new Error(`Recurso ${id}: módulo pronto inexistente "${family}"`)
    parsed = { status: 'pronto', family }
  } else {

    const pending = model.startsWith('?')
    const [shape, dims, material] = (pending ? model.slice(1) : model).split(' ')
    const size = dims.split('x').map(Number) as Vec3
    if (!SHAPES.has(shape as BlockoutShape) || size.length !== 3 || !size.every((n) => n > 0) || !(material in BLOCK_MATERIALS)) throw new Error(`Recurso ${id}: blocagem inválida "${model}"`)
    parsed = { status: pending ? 'pendente' : 'esculpido', shape: shape as BlockoutShape, size, material: material as MaterialKey }
  }
  const stack = Math.max(max, weight >= 10 ? 1 : weight >= 3 ? 2 : weight >= 1 ? 5 : weight >= 0.2 ? 10 : weight >= 0.05 ? 25 : 50)
  return {
    id, label, category, rarity: RARITY[rarity], weight, quantity: [min, max], stack,
    uses: words<Use>(uses, USE_LABELS, id, 'uso'), containers: words<Container>(containers, CONTAINER_LABELS, id, 'recipiente'), sites: affinity,
    display: display ?? (parsed.status === 'pronto' ? parsed.family : DISPLAY[category]), model: parsed,
  }
}

