export const RESOURCE_BY_ID = new Map(RESOURCES.map((resource) => [resource.id, resource]))
export const RESOURCES_BY_CONTAINER = new Map<Container, Resource[]>()
for (const resource of RESOURCES) for (const container of resource.containers) {
  const list = RESOURCES_BY_CONTAINER.get(container) ?? []
  list.push(resource)
  RESOURCES_BY_CONTAINER.set(container, list)
}

export const PENDING_RESOURCES = RESOURCES.filter((resource) => resource.model.status === 'pendente')

export const SCULPTED_RESOURCES = RESOURCES.filter((resource) => resource.model.status === 'esculpido')
